// Synthetic production-path fixture. No game, SDK or captured shader inputs.
// Uses known generated bytes only; this is not the separate texture-readback audit.
#include "../nvn/nvn_mtl.m"
#include <math.h>
uint64_t g_t0_ns;
int dm_guest_as_contains(uintptr_t address) { (void)address; return 0; }
void *front_metal_layer(void) { return NULL; }
module_t *module_of(const void *p) { (void)p; return NULL; }
module_t g_mod[MAX_MOD]; int g_nmod;
void svc_thread_dump(void) {}
uint64_t now_ns(void) { return bp_now(); }
static int checks, fails;
#define CHECK(c, msg) do { checks++; if (!(c)) { fails++; fprintf(stderr, "FAIL: %s\n", msg); } } while (0)
static void checked_drain(void) { mtl_drain(); CHECK(!mtl_last_commit_error(), "completed synthetic submission has no GPU error"); }
static NSUInteger edge(NSUInteger n, NSUInteger l) { return MAX(n >> l, 1u); }
static uint8_t pattern(unsigned seed, unsigned sl, unsigned lv) { return (uint8_t)(seed + sl * 7 + lv * 13); }
static void fill(id<MTLTexture> t, int bc, unsigned seed) {
    NSUInteger block = bc ? 4 : 1, unit = bc || t.pixelFormat == MTLPixelFormatRGBA32Float ? 16 : 4;
    for (NSUInteger sl = 0; sl < t.arrayLength; sl++) for (NSUInteger l = 0; l < t.mipmapLevelCount; l++) {
        NSUInteger w = edge(t.width, l), h = edge(t.height, l), row = ((w + block - 1) / block * unit + 255) & ~255u;
        NSUInteger size = row * ((h + block - 1) / block);
        id<MTLBuffer> b = [g_dev newBufferWithLength:size options:MTLResourceStorageModeShared];
        memset(b.contents, pattern(seed, (unsigned)sl, (unsigned)l), size); res_add(b);
        enc_b_copy_buffer_texture(blit(), b, 0, row, size, MTLSizeMake(w, h, 1), t, sl, l, MTLOriginMake(0, 0, 0));
        defer_obj_release(b);
    }
}
static id<MTLBuffer> read_six(id<MTLTexture> t, int bc, NSUInteger *used) {
    NSUInteger block = bc ? 4 : 1, unit = bc ? 16 : 4, total = 0;
    for (NSUInteger l = 0; l < t.mipmapLevelCount; l++) {
        NSUInteger w = edge(t.width, l), h = edge(t.height, l), row = ((w + block - 1) / block * unit + 255) & ~255u;
        total += row * ((h + block - 1) / block) * 6;
    }
    id<MTLBuffer> b = [g_dev newBufferWithLength:total options:MTLResourceStorageModeShared]; res_add(b);
    NSUInteger off = 0;
    for (NSUInteger l = 0; l < t.mipmapLevelCount; l++) {
        NSUInteger w = edge(t.width, l), h = edge(t.height, l), row = ((w + block - 1) / block * unit + 255) & ~255u;
        NSUInteger size = row * ((h + block - 1) / block);
        for (NSUInteger f = 0; f < 6; f++) {
            enc_b_copy_texture_buffer(blit(), t, f, l, MTLOriginMake(0, 0, 0), MTLSizeMake(w, h, 1), b, off, row, size); off += size;
        }
    }
    *used = total; return b;
}
static void check_six(id<MTLTexture> t, id<MTLBuffer> b, int bc, unsigned seed, unsigned sl0, unsigned lv0) {
    NSUInteger block = bc ? 4 : 1, unit = bc ? 16 : 4, off = 0;
    for (NSUInteger l = 0; l < t.mipmapLevelCount; l++) {
        NSUInteger w = edge(t.width, l), h = edge(t.height, l), cols = (w + block - 1) / block * unit;
        NSUInteger rows = (h + block - 1) / block, row = (cols + 255) & ~255u;
        for (NSUInteger f = 0; f < 6; f++) { int ok = 1;
            for (NSUInteger y = 0; y < rows; y++) for (NSUInteger x = 0; x < cols; x++)
                ok &= ((const uint8_t *)b.contents)[off + y * row + x] == pattern(seed, sl0, lv0 + (unsigned)l);
            CHECK(ok, "every face/mip has exact source-view bytes"); off += rows * row;
        }
    }
}
static void copy_case(int bc, int subview) {
    MTLPixelFormat pf = bc == 2 ? MTLPixelFormatBC7_RGBAUnorm : bc ? MTLPixelFormatBC7_RGBAUnorm_sRGB : MTLPixelFormatRGBA8Unorm;
    MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:pf width:32 height:32 mipmapped:YES];
    d.storageMode = MTLStorageModePrivate; d.usage = MTLTextureUsageShaderRead;
    if (subview) { d.textureType = MTLTextureType2DArray; d.arrayLength = 4; }
    id<MTLTexture> base = [g_dev newTextureWithDescriptor:d]; CHECK(base != nil, "private synthetic source created"); if (!base) return;
    res_add(base); unsigned lv0 = subview ? 2 : 0, sl0 = subview ? 3 : 0;
    MTLTextureSwizzleChannels sw = MTLTextureSwizzleChannelsMake(MTLTextureSwizzleBlue, MTLTextureSwizzleRed, MTLTextureSwizzleOne, MTLTextureSwizzleZero);
    id<MTLTexture> src = [base newTextureViewWithPixelFormat:pf textureType:MTLTextureType2D levels:NSMakeRange(lv0, 6 - lv0) slices:NSMakeRange(sl0, 1) swizzle:sw];
    CHECK(src != nil, "offset/swizzled source view created"); if (!src) return;
    mtl_sub_begin(); fill(base, bc, 21); cube_copy_begin();
    CHECK(cube_copy_prepare_texture(123, src, MTLTextureTypeCube), "first copy prepared");
    uint64_t rid = 0;
    CHECK(cube_copy_bound(src, MTLTextureTypeCube, &rid) == nil, "helper/geometry scope cannot bind another consumer's cube");
    g_cube_copy_binding = 1;
    id<MTLTexture> cube = cube_copy_bound(src, MTLTextureTypeCube, &rid);
    CHECK(cube && rid == cube.gpuResourceID._impl && cube.pixelFormat == pf, "bound cube has same format and nonzero resource ID");
    CHECK(cube.width == src.width && cube.mipmapLevelCount == src.mipmapLevelCount, "selected mip range retained");
    CHECK(cube.swizzle.red == sw.red && cube.swizzle.green == sw.green && cube.swizzle.blue == sw.blue && cube.swizzle.alpha == sw.alpha, "sampling swizzle retained");
    if (!cube) { mtl_sub_commit(); checked_drain(); return; }
    uint64_t made = g_cube_copy_made, refresh = g_cube_copy_refresh;
    CHECK(cube_copy_prepare_texture(123, src, MTLTextureTypeCube) && g_cube_copy_refresh == refresh, "same consumer deduplicates copy");
    NSUInteger bytes; id<MTLBuffer> first = read_six(cube, bc, &bytes);
    fill(base, bc, 77); cube_copy_begin();
    CHECK(cube_copy_bound(src, MTLTextureTypeCube, &rid) == nil, "unchanged source pointer does not reuse previous content");
    CHECK(cube_copy_prepare_texture(123, src, MTLTextureTypeCube), "in-place GPU mutation refreshed");
    g_cube_copy_binding = 1;
    CHECK(cube_copy_bound(src, MTLTextureTypeCube, &rid) == cube && g_cube_copy_made == made, "same cube allocation reused after mutation");
    id<MTLBuffer> second = read_six(cube, bc, &bytes);
    mtl_sub_commit(); checked_drain();
    check_six(cube, first, bc, 21, sl0, lv0); check_six(cube, second, bc, 77, sl0, lv0);
    mtl_sub_begin(); fill(base, bc, 113); cube_copy_begin();
    CHECK(cube_copy_prepare_texture(123, src, MTLTextureTypeCube) && g_cube_copy_made == made, "next submission refreshes without reallocating");
    id<MTLBuffer> third = read_six(cube, bc, &bytes); mtl_sub_commit(); checked_drain();
    check_six(cube, third, bc, 113, sl0, lv0); res_remove(third);
    res_remove(first); res_remove(second); res_remove(base);
}
static void capacity_case(void) {
    for (int i = 0; i < NVN_CUBE_COPY_SLOTS; i++) cube_copy_drop(i);
    CHECK(!g_cube_copy_bytes, "completed allocations released and budget reset");
    NSMutableArray *sources = [NSMutableArray array];
    mtl_sub_begin(); cube_copy_begin();
    for (int i = 0; i <= NVN_CUBE_COPY_SLOTS; i++) {
        MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:1 height:1 mipmapped:NO];
        d.storageMode = MTLStorageModePrivate; d.usage = MTLTextureUsageShaderRead;
        id<MTLTexture> src = [g_dev newTextureWithDescriptor:d]; res_add(src); [sources addObject:src]; fill(src, 0, (unsigned)i);
        int ok = cube_copy_prepare_texture(1000+i, src, MTLTextureTypeCubeArray);
        CHECK(ok == (i < NVN_CUBE_COPY_SLOTS), "all in-flight slots refuse overflow without eviction");
        CHECK(g_cube_copy_bytes <= NVN_CUBE_COPY_BYTES, "allocation budget stays bounded");
    }
    mtl_sub_commit(); checked_drain();
    mtl_sub_begin(); cube_copy_begin();
    CHECK(cube_copy_prepare_texture(2000, sources.lastObject, MTLTextureTypeCubeArray), "completed fence permits eviction");
    mtl_sub_commit(); checked_drain();
    for (id<MTLTexture> src in sources) res_remove(src);
    for (int i = 0; i < NVN_CUBE_COPY_SLOTS; i++) cube_copy_drop(i);
}
static void budget_case(void) {
    for (int i = 0; i < NVN_CUBE_COPY_SLOTS; i++) cube_copy_drop(i);
    NSMutableArray *sources = [NSMutableArray array]; int admitted = 0, refused = 0;
    mtl_sub_begin(); cube_copy_begin();
    for (int i = 0; i < NVN_CUBE_COPY_SLOTS; i++) {
        MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA32Float width:256 height:256 mipmapped:YES];
        d.storageMode = MTLStorageModePrivate; d.usage = MTLTextureUsageShaderRead;
        id<MTLTexture> src = [g_dev newTextureWithDescriptor:d]; res_add(src); [sources addObject:src]; fill(src, 0, 0);
        if (!cube_copy_prepare_texture(3000+i, src, MTLTextureTypeCube)) { refused = 1; break; }
        admitted++; CHECK(g_cube_copy_bytes <= NVN_CUBE_COPY_BYTES, "actual charged allocations remain within 16 MiB");
    }
    CHECK(admitted > 0 && admitted < NVN_CUBE_COPY_SLOTS && refused, "byte budget refuses large allocations before the slot limit");
    mtl_sub_commit(); checked_drain();
    for (id<MTLTexture> src in sources) res_remove(src);
    for (int i = 0; i < NVN_CUBE_COPY_SLOTS; i++) cube_copy_drop(i);
}

// Recycle both the registration ID and the caller's tex_t storage. Exercise the
// scalar shader preparation/lookup path, not only the low-level copy helper.
static id<MTLTexture> registered_source(int tid) {
    pthread_mutex_lock(&g_rmu); id<MTLTexture> t = tex_by_id(tid); pthread_mutex_unlock(&g_rmu); return t;
}
static void registered_reuse_case(void) {
    const int tid = 4200;
    tex_t t = {.magic=MAGIC('T','E','X',0), .serial=987660};
    t.d = (nvn_texdesc){.target=NVN_TEXTURE_TARGET_2D, .format=NVN_FORMAT_RGBA8, .width=8, .height=8, .depth=1, .levels=4, .samples=1};
    id<MTLTexture> a = [g_dev newTextureWithDescriptor:tex_desc(&t, 0)];
    id<MTLTexture> b = [g_dev newTextureWithDescriptor:tex_desc(&t, 0)];
    CHECK(a && b, "descriptor-reuse synthetic sources created"); if (!a || !b) return;
    res_add(a); res_add(b); serial_put(t.serial, a); mtl_reg_tex(tid, &t, NULL);
    NvShader *sh = [NvShader new]; sh->rf.nb = 1;
    sh->rf.b[0] = (nvn_rbind){.kind=NVN_RB_TEX, .reg=0, .dtt=MTLTextureTypeCube, .dpf=NVN_DPF_FLOAT};
    S.tex[5][0] = tid;
    mtl_sub_begin(); fill(a, 0, 31); fill(b, 0, 93); cube_copy_begin();
    cube_copy_prepare_shader(sh, 5); g_cube_copy_binding = 1;
    uint64_t rid = 0; NSUInteger bytes;
    id<MTLTexture> cube_a = tex_fit(tid, registered_source(tid), MTLTextureTypeCube, &rid);
    CHECK(cube_a && cube_a == cube_copy_bound(a, MTLTextureTypeCube, &rid), "registered shader source resolves to prepared cube");
    id<MTLBuffer> first = cube_a ? read_six(cube_a, 0, &bytes) : nil;
    t.serial++; serial_put(t.serial, b); mtl_reg_tex(tid, &t, NULL);
    CHECK(registered_source(tid) == b, "same descriptor ID and tex_t address resolve replacement source");
    CHECK(cube_copy_bound(b, MTLTextureTypeCube, &rid) == nil, "registration replacement cannot reuse old source snapshot");
    cube_copy_prepare_shader(sh, 5); g_cube_copy_binding = 1;
    id<MTLTexture> cube_b = tex_fit(tid, registered_source(tid), MTLTextureTypeCube, &rid);
    CHECK(cube_b && cube_b != cube_a && cube_b == cube_copy_bound(b, MTLTextureTypeCube, &rid), "replacement source gets its own prepared cube");
    id<MTLBuffer> second = cube_b ? read_six(cube_b, 0, &bytes) : nil;
    uint64_t made = g_cube_copy_made;
    mtl_sub_commit();   // Do not drain: the next submission must order after this one.
    mtl_sub_begin(); fill(b, 0, 151); cube_copy_begin(); cube_copy_prepare_shader(sh, 5); g_cube_copy_binding = 1;
    CHECK(tex_fit(tid, registered_source(tid), MTLTextureTypeCube, &rid) == cube_b && g_cube_copy_made == made, "registered source refreshes across submissions without reallocating");
    id<MTLBuffer> third = cube_b ? read_six(cube_b, 0, &bytes) : nil;
    // Finalize the registrations while both submissions may still be running.
    mtl_reg_tex(tid, NULL, NULL); serial_del(987660); serial_del(987661); S.tex[5][0] = 0;
    a = nil; b = nil;
    mtl_sub_commit(); checked_drain();
    if (cube_a) check_six(cube_a, first, 0, 31, 0, 0);
    if (cube_b) { check_six(cube_b, second, 0, 93, 0, 0); check_six(cube_b, third, 0, 151, 0, 0); }
    res_remove(first); res_remove(second); res_remove(third);
}

static void pending_clear_case(void) {
    tex_t t = {.magic=MAGIC('T','E','X',0), .serial=987654};
    t.d = (nvn_texdesc){.target=NVN_TEXTURE_TARGET_2D, .format=NVN_FORMAT_RGBA8, .width=4, .height=4, .depth=1, .levels=1, .samples=1};
    id<MTLTexture> src = [g_dev newTextureWithDescriptor:tex_desc(&t, 0)]; res_add(src); serial_put(t.serial, src);
    mtl_sub_begin(); fill(src, 0, 7);
    R.has_rt = 1; R.rt.n = 1; R.rt.color[0] = &t; R.clear_c[0] = 1; R.cc[0] = MTLClearColorMake(0.5,0.5,0.5,0.5);
    cube_copy_begin(); CHECK(cube_copy_prepare_texture(321, src, MTLTextureTypeCube), "pending clear source copied");
    g_cube_copy_binding = 1; uint64_t rid; id<MTLTexture> cube = cube_copy_bound(src, MTLTextureTypeCube, &rid);
    CHECK(!R.clear_c[0], "load-action clear landed before snapshot");
    NSUInteger bytes; id<MTLBuffer> result = cube ? read_six(cube, 0, &bytes) : nil;
    mtl_sub_commit(); checked_drain(); if (cube) check_six(cube, result, 0, 128, 0, 0);
    memset(&R, 0, sizeof R); res_remove(result); serial_del(t.serial);
}
static void sample_swizzle_case(void) {
    MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:1 height:1 mipmapped:NO];
    d.storageMode = MTLStorageModePrivate; d.usage = MTLTextureUsageShaderRead;
    id<MTLTexture> base = [g_dev newTextureWithDescriptor:d]; res_add(base);
    MTLTextureSwizzleChannels sw = MTLTextureSwizzleChannelsMake(MTLTextureSwizzleBlue, MTLTextureSwizzleRed, MTLTextureSwizzleOne, MTLTextureSwizzleZero);
    id<MTLTexture> src = [base newTextureViewWithPixelFormat:base.pixelFormat textureType:MTLTextureType2D levels:NSMakeRange(0,1) slices:NSMakeRange(0,1) swizzle:sw];
    const uint8_t data[16] = {17,33,65,129}; id<MTLBuffer> input = [g_dev newBufferWithBytes:data length:16 options:MTLResourceStorageModeShared]; res_add(input);
    mtl_sub_begin(); enc_b_copy_buffer_texture(blit(), input, 0, 16, 16, MTLSizeMake(1,1,1), base, 0, 0, MTLOriginMake(0,0,0));
    cube_copy_begin(); CHECK(cube_copy_prepare_texture(4000, src, MTLTextureTypeCube), "sample cube prepared");
    uint64_t rid; g_cube_copy_binding = 1; id<MTLTexture> cube = cube_copy_bound(src, MTLTextureTypeCube, &rid);
    mtl_sub_commit(); checked_drain();
    NSError *error = nil;
    NSString *code = @"#include <metal_stdlib>\nusing namespace metal;\nkernel void check(texturecube<float> t [[texture(0)]], device float4 *out [[buffer(0)]], uint i [[thread_position_in_grid]]) { constexpr sampler s(coord::normalized, filter::nearest); float3 d[6] = {float3(1,0,0),float3(-1,0,0),float3(0,1,0),float3(0,-1,0),float3(0,0,1),float3(0,0,-1)}; out[i] = t.sample(s,d[i],level(0)); }";
    id<MTLLibrary> lib = [g_dev newLibraryWithSource:code options:nil error:&error];
    id<MTLComputePipelineState> ps = lib ? [g_dev newComputePipelineStateWithFunction:[lib newFunctionWithName:@"check"] error:&error] : nil;
    CHECK(ps && cube, "synthetic cube sampler compiled");
    if (ps && cube) {
        id<MTLBuffer> output = [g_dev newBufferWithLength:6*16 options:MTLResourceStorageModeShared];
        id<MTLCommandBuffer> cb = q_cb(); id<MTLComputeCommandEncoder> e = [cb computeCommandEncoder];
        [e setComputePipelineState:ps]; [e setTexture:cube atIndex:0]; [e setBuffer:output offset:0 atIndex:0];
        [e dispatchThreadgroups:MTLSizeMake(6,1,1) threadsPerThreadgroup:MTLSizeMake(1,1,1)]; [e endEncoding]; [cb commit]; [cb waitUntilCompleted];
        CHECK(cb.status == MTLCommandBufferStatusCompleted, "synthetic sampling completed");
        const float *out = output.contents; const float expected[4] = {65/255.f,17/255.f,1,0};
        for (int face = 0; face < 6; face++) for (int k = 0; k < 4; k++) CHECK(fabsf(out[face*4+k] - expected[k]) < 0.001f, "six directions preserve mapped channels");
    }
    res_remove(input); res_remove(base);
    d.pixelFormat = MTLPixelFormatRGBA8Uint;
    id<MTLTexture> integer = [g_dev newTextureWithDescriptor:d];
    CHECK(integer && !cube_copy_shape(integer, MTLTextureTypeCube), "integer format cannot enter a float cube fallback");
}

static int disabled_case(void) {
    MTLTextureDescriptor *d = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:32 height:32 mipmapped:YES];
    d.storageMode = MTLStorageModePrivate; d.usage = MTLTextureUsageShaderRead;
    id<MTLTexture> src = [g_dev newTextureWithDescriptor:d];
    mtl_sub_begin(); cube_copy_begin();
    CHECK(!cube_copy_prepare_texture(123, src, MTLTextureTypeCube), "disabled mode cannot prepare a copy");
    g_cube_copy_binding = 1; uint64_t rid = 0;
    id<MTLTexture> cube = tex_fit(123, src, MTLTextureTypeCube, &rid);
    CHECK(cube == dummy_tex(MTLTextureTypeCube, NVN_DPF_FLOAT), "disabled mode keeps existing zero cube");
    CHECK(!g_cube_copy_made && !g_cube_copy_refresh && !g_cube_copy_bytes && !g_gp_copies, "disabled mode allocates/copies no compatibility resources");
    mtl_sub_commit(); checked_drain(); CHECK(!mtl_last_commit_error(), "disabled fixture has no GPU submission error"); return fails != 0;
}
int main(int argc, char **argv) { @autoreleasepool {
    int disabled = argc > 1 && !strcmp(argv[1], "--disabled");
    setenv("DM_NVN_CUBE_COPY", disabled ? "0" : "1", 1); mtl_init();
    if (disabled) return disabled_case();
    copy_case(0, 0); copy_case(0, 1);
    if ([g_dev supportsBCTextureCompression]) { copy_case(1, 0); copy_case(1, 1); copy_case(2, 0); copy_case(2, 1); }
    else { fprintf(stderr, "FAIL: BC7 support required for the complete fixture\n"); fails++; }
    pending_clear_case(); sample_swizzle_case(); registered_reuse_case(); capacity_case(); budget_case();
    CHECK(!mtl_last_commit_error(), "synthetic fixture has no GPU submission error");
    printf("synthetic cube copy: %d checks, %d failed\n", checks, fails); return fails != 0;
} }
